insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 15, 'E disse: Bendito seja o SENHOR Deus de Israel, que falou de sua boca a Davi meu pai, e com sua mão o cumpriu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 16, 'Desde o dia que tirei meu povo Israel do Egito, não escolhi cidade de todas as tribos de Israel para edificar casa na qual estivesse meu nome, ainda que escolhi a Davi para que presidisse em meu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 17, 'E Davi meu pai teve no coração edificar casa ao nome do SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 18, 'Mas o SENHOR disse a Davi meu pai: Quanto a haver tu tido no coração edificar casa a meu nome, bem fizeste em ter tal vontade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 19, 'Porém tu não edificarás a casa, mas sim teu filho que sairá de teus lombos, ele edificará casa a meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 20, 'E o SENHOR verificou sua palavra que havia dito; que me levantei eu em lugar de Davi meu pai, e sentei-me no trono de Israel, como o SENHOR havia dito, e edifiquei a casa ao nome do SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 21, 'E pus nela lugar para a arca, na qual está o pacto do SENHOR, que ele fez com nossos pais quando os tirou da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 22, 'Logo Salomão se pôs diante do altar do SENHOR, na presença de toda a congregação de Israel; e estendeu suas mãos para os céus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 23, 'Disse: Ó SENHOR, Deus de Israel, não há Deus como tu, nem acima nos céus nem abaixo na terra, que guardas o pacto e a misericórdia aos teus servos que andam com todo o seu coração diante de ti;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 24, 'que guardaste ao teu servo Davi, meu pai, o que lhe disseste: pois com a tua boca o disseste, e com a tua mão o cumpriste, como hoje se sucede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 25, 'Agora, pois, ó SENHOR Deus de Israel, guarda ao teu servo Davi, meu pai, o que lhe prometeste, dizendo: Não te faltará sucessor diante de mim que se assente no trono de Israel; contanto que os teus descendentes guardem o seu caminho para andarem diante de mim como tu andaste diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 26, 'Portanto agora, ó Deus de Israel, cumpra-se a tua palavra que disseste ao teu servo Davi, meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 27, 'Mas, na verdade, haveria Deus de habitar na terra? Eis que os céus, e até o céu dos céus, não te podem conter; quanto menos esta casa que eu edifiquei!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 28, 'Contudo, volta-te à oração do teu servo, e à sua súplica, ó SENHOR, meu Deus, para ouvires o clamor e a oração que o teu servo faz hoje diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 29, 'Que teus olhos noite e dia estejam abertos sobre esta casa, sobre este lugar do qual disseste: Meu nome estará ali; e que ouças a oração que teu servo fizer neste lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 30, 'Ouve, pois, a oração do teu servo, e do teu povo Israel; quando orarem neste lugar, também tu ouve no lugar da tua habitação nos céus; que ouças e perdoes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 31, 'Quando alguém pecar contra o seu próximo, e lhe impuserem um juramento de maldição, e o juramento de maldição vier diante do teu altar nesta casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 32, 'ouve tu nos céus, age, e julga teus servos, condenando ao culpado, fazendo recair o seu proceder sobre a sua cabeça, e inocentando ao justo, para dar-lhe conforme a sua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 33, 'Quando teu povo Israel for derrotado diante do inimigo, por haver pecado contra ti, e a ti se converterem, e confessarem o teu nome, e orarem, e suplicarem a ti nesta casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 34, 'ouve tu nos céus, e perdoa o pecado do teu povo Israel, e traze-os de volta à terra que deste aos seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 35, 'Quando os céus se fecharem, e não chover, por terem pecado contra ti, e orarem voltados a este lugar, e confessarem o teu nome, e se converterem do pecado deles, quando tu os afligires,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 36, 'ouve tu nos céus, e perdoa o pecado dos teus servos e do teu povo Israel, ensinando-lhes o bom caminho em que devem andar; e dá chuva na tua terra que deste ao teu povo por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 37, 'Quando nesta herra houver fome, ou pestilência, ou ferrugem, ou mofo, ou gafanhoto, ou pulgão, quando o seu inimigo o tiverem cercados na terra de suas cidades; qualquer praga ou doença,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 38, 'toda oração e toda súplica que qualquer homem, ou todo o teu povo Israel [fizer] , quando qualquer um reconhecer a ferida de seu coração, e estender suas mãos para esta casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 39, 'ouve tu nos céus, o lugar de tua habitação, e perdoa, age, e dá a cada um conforme a todos os seus caminhos, cujo coração tu conheces (porque somente tu conheces o coração de todos os filhos dos homens),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 40, 'para que te temam todos os dias que viverem na terra que deste aos nossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 41, 'Também o estrangeiro, que não for do teu povo Israel, vier de terras distantes por causa do teu nome,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 42, '(porque ouvirão do teu grande nome, e da tua mão forte, e do teu braço estendido), e vier orar voltado a esta casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 43, 'ouve tu nos céus, o lugar da tua habitação, e faze conforme a tudo o que o estrangeiro a ti clamar, a fim de que todos os povos da terra conheçam o teu nome, e te temam como o teu povo Israel, e saibam que o teu nome é invocado sobre esta casa que eu edifiquei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 44, 'Quando o teu povo sair em batalha contra o seu inimigo, pelo caminho que os enviares, e orarem ao SENHOR, voltados à cidade que tu escolheste, e a esta casa que eu edifiquei ao teu nome,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 45, 'ouve, então, nos céus a sua oração e a sua súplica, e faze-lhes justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 46, 'Quando pecarem contra ti (porque ninguém há que não peque) e te irares contra eles, e os entregares ao inimigo, para que os prendam e os levem à terra do inimigo, esteja longe ou próxima,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 47, 'e na terra onde forem levados cativos eles caírem em si, e se converterem, e te suplicarem na terra do seu cativeiro, dizendo: Pecamos, praticamos perversidade, cometemos maldade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 48, 'e se converterem a ti com todo o seu coração e com toda a sua alma, na terra do seus inimigos que os levaram cativos, e orarem a ti voltados à sua terra, que deste a seus pais, à cidade que tu escolheste e a casa que edifiquei ao teu nome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 49, 'Tu ouvirás nos céus, na habitação de tua morada, sua oração e sua súplica, e lhes farás direito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 50, 'E perdoa ao teu povo que houver pecado contra ti, e todas suas transgressões com que se houverem rebelado contra ti; e concede-lhes misericórdia da parte dos que os teem cativos, para que tenham compaixão deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 51, 'Porque eles são o teu povo e a tua propriedade, que tiraste do Egito, do meio do forno de ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 52, 'Que os teus olhos estejam abertos à súplica do teu servo e à súplica do teu povo Israel, a fim de os ouvires em tudo pelo qual clamarem a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 53, 'Pois tu os separaste de todos os povos da terra para que fossem propriedade tua, como o disseste por meio do teu servo Moisés, quando tiraste os nossos antepassados do Egito, ó Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 54, 'E sucedeu que, quando Salomão acabou de fazer ao SENHOR toda esta oração e súplica, estando de joelhos e com as mãos estendidas aos céus, levantou-se de diante do altar do SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 55, 'pôs-se de pé, e abençoou a toda a congregação de Israel, dizendo em alta voz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 56, 'Bendito seja o SENHOR, que deu repouso ao seu povo Israel, conforme a tudo o que disse; nenhuma palavra falhou de todas as suas boas promessas que falou por meio de seu servo Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 57, 'Seja conosco o SENHOR, nosso Deus, como foi com nossos antepassados; que ele não nos desampare, nem nos deixe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 58, 'mas incline os nossos corações a ele, para que andemos em todos os seus caminhos, e guardemos os seus mandamentos, seus estatutos e suas ordenanças, os quais ele prescreveu aos nossos antepassados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 59, 'E que estas minhas palavras com que supliquei diante do SENHOR estejam próximas do SENHOR, nosso Deus, de dia e de noite, para que ele proteja a causa de seu servo, e a causa de seu povo Israel, cada coisa em seu dia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 60, 'a fim de que todos os povos da terra saibam que o SENHOR é Deus, e que não há outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 61, 'Seja, pois, o vosso coração íntegro com o SENHOR, nosso Deus, para andardes nos seus estatutos, e guardardes os seus mandamentos, como hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 62, 'Então o rei, e todo Israel com ele, ofereceram sacrifícios diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 63, 'E Salomão sacrificou por sacrifícios pacíficos, os quais ofereceu ao SENHOR vinte e dois mil bois, e cento vinte mil ovelhas. Assim o rei e todos os filhos de Israel dedicaram a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 64, 'Naquele mesmo dia o rei consagrou o meio do pátio que ficava diante da casa do SENHOR; porque ali ofereceu os holocaustos e as ofertas de cereais, e a gordura das ofertas pacíficas; porque o altar de bronze que [estava] diante do SENHOR era muito pequeno para caber nele os holocaustos, as ofertas de cereais, e a gordura das ofertas pacíficas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 65, 'Naquele tempo Salomão celebrou a festa, e com ele todo Israel, uma grande congregação, vinda desde como Lebo-Hamate até o rio do Egito, perante o SENHOR, nosso Deus, por sete dias e mais sete dias, isto é, por catorze dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 8, 66, 'E no oitavo dia despediu ao povo; e eles, bendizendo ao rei, foram-se às suas moradas alegres e jubilosos de coração por todo o bem que o SENHOR havia feito ao seu servo Davi, e ao seu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 1, 'E quando Salomão havia acabado a obra da casa do SENHOR, e a casa real, e tudo o que Salomão quis fazer,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 2, 'o SENHOR apareceu a Salomão a segunda vez, como lhe havia aparecido em Gibeão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 3, 'E disse-lhe o SENHOR: Eu ouvido tua oração e teu rogo, que fizeste em minha presença. Eu santifiquei esta casa que tu hás edificado, para pôr meu nome nela para sempre; e nela estarão meus olhos e meu coração todos os dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 4, 'E se tu andares diante de mim, como andou Davi teu pai, em integridade de coração e em equidade, fazendo todas as coisas que eu te ei mandado, e guardando meus estatutos e meus direitos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 5, 'Eu afirmarei o trono de teu reino sobre Israel para sempre, como falei a Davi teu pai, dizendo: Não faltará de ti homem no trono de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 6, 'Mas se obstinadamente vos apartardes de mim vós e vossos filhos, e não guardardes meus mandamentos e meus estatutos que eu pus diante de vós, mas sim que fordes e servirdes a deuses alheios, e os adorardes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 7, 'Eu cortarei a Israel de sobre a face da terra que lhes entreguei; e esta casa que santifiquei a meu nome, eu a lançarei de diante de mim, e Israel será por provérbio e fábula a todos os povos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 8, 'E esta casa que estava em estima, qualquer um que passar por ela se pasmará, e assoviará, e dirá: Por que fez assim o SENHOR a esta terra, e a esta casa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 9, 'E dirão: Porquanto deixaram ao SENHOR seu Deus, que havia tirado a seus pais da terra do Egito, e lançaram mão a deuses alheios, e os adoraram, e os serviram: por isso trouxe o SENHOR sobre eles todo este mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 10, 'E aconteceu ao fim de vinte anos, em que Salomão havia edificado as duas casas, a casa do SENHOR e a casa real,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 11, '(Para as quais Hirão rei de Tiro, havia trazido a Salomão madeira de cedro e de faia, e quanto ouro ele quis), que o rei Salomão deu a Hirão vinte cidades em terra de Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 12, 'E saiu Hirão de Tiro para ver as cidades que Salomão lhe havia dado, e não lhe contentaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 13, 'E disse: Que cidades são estas que me deste, irmão? E pôs-lhes por nome, a terra de Cabul, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 14, 'E havia Hirão enviado ao rei cento e vinte talentos de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 15, 'E esta é a razão do tributo que o rei Salomão impôs para edificar a casa do SENHOR, e sua casa, e a Milo, e o muro de Jerusalém, e a Hazor, e Megido, e Gezer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 16, 'Faraó, o rei do Egito, havia subido e tomado a Gezer, e a queimado, e havia matado os cananeus que habitavam a cidade, e dado-a em presente à sua filha, a mulher de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 17, 'Restaurou, pois Salomão a Gezer, e à baixa Bete-Horom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 18, 'E a Baalate, e a Tadmor em terra do deserto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 19, 'Também todas as cidades de onde Salomão tinha armazéns, e as cidades dos carros, e as cidades de cavaleiros, e tudo o que Salomão desejou edificar em Jerusalém, no Líbano, e em toda a terra de seu senhorio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 20, 'A todos os povos que restaram dos amorreus, heteus, perizeus, heveus, jebuseus, que não foram dos filhos de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 21, 'A seus filhos que restaram na terra depois deles, que os filhos de Israel não puderam acabar, fez Salomão que servissem com tributo até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 22, 'Mas a ninguém dos filhos de Israel impôs Salomão serviço, mas sim que eram homens de guerra, ou seus criados, ou seus príncipes, ou seus capitães, ou comandantes de seus carros, ou sua cavaleiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 23, 'E os que Salomão havia feito chefes e líderes sobre as obras, eram quinhentos e cinquenta, os quais estavam sobre o povo que trabalhava naquela obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 24, 'E subiu a filha de Faraó da cidade de Davi a sua casa que Salomão lhe havia edificado: então edificou ele a Milo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 25, 'E oferecia Salomão três vezes cada um ano holocaustos e pacíficos sobre o altar que ele edificou ao SENHOR, e queimava incenso sobre o que estava diante do SENHOR, depois que a casa foi acabada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 26, 'Fez também o rei Salomão navios em Eziom-Geber, que é junto a Elate na beira do mar Vermelho, na terra de Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 27, 'E enviou Hirão neles a seus servos, marinheiros e destros no mar, com os servos de Salomão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 9, 28, 'Os quais foram a Ofir, e tomaram dali ouro, quatrocentos e vinte talentos, e trouxeram-no ao rei Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 1, 'E ouvindo a rainha de Sabá a fama de Salomão no nome do SENHOR, veio a provar-lhe com perguntas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 2, 'E veio a Jerusalém com muito grande comitiva, com camelos carregados de especiarias, e ouro em grande abundância, e pedras preciosas: e quando veio a Salomão, propôs-lhe todo o que em seu coração tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 3, 'E Salomão lhe declarou todas suas palavras: nenhuma coisa se lhe escondeu ao rei, que não lhe declarasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 4, 'E quando a rainha de Sabá viu toda a sabedoria de Salomão, e a casa que havia edificado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 5, 'Também a comida de sua mesa, o assento de seus servos, o estado e roupas dos que lhe serviam, seus mestres-salas, e seus holocaustos que sacrificava na casa do SENHOR, ficou pasma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 6, 'E disse ao rei: Verdade é o que ouvi em minha terra de tuas coisas e de tua sabedoria;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 7, 'Mas eu não o cria, até que vim, e meus olhos viram, que nem ainda a metade foi o que se me disse: é maior tua sabedoria e bem que a fama que eu havia ouvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 8, 'Bem-aventurados teus homens, ditosos estes teus servos, que estão continuamente diante de ti, e ouvem tua sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 9, 'o SENHOR teu Deus seja bendito, que se agradou de ti para te pôr no trono de Israel; porque o SENHOR amou sempre a Israel, e te pôs por rei, para que faças direito e justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 10, 'E deu ela ao rei cento e vinte talentos de ouro, e muita especiaria, e pedras preciosas: nunca veio tão grande quantidade de especiarias, como a rainha de Sabá deu ao rei Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 11, 'A frota de Hirão que havia trazido o ouro de Ofir, trazia também de Ofir muita madeira de sândalo, e pedras preciosas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 12, 'E da madeira de sândalo fez o rei balaústres para a casa do SENHOR, e para as casas reais, harpas também e saltérios para os cantores: nunca veio tanta madeira de sândalo, nem se há visto até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 13, 'E o rei Salomão deu à rainha de Sabá tudo o que quis, e tudo o que pediu, ademais do que Salomão lhe deu como da mão do rei Salomão. E ela se voltou, e se foi a sua terra com seus criados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 14, 'O peso do ouro que Salomão tinha de renda cada um ano era seiscentos sessenta e seis talentos de ouro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 15, 'Sem o dos mercadores, e da contratação de especiarias, e de todos os reis de Arábia, e dos principais da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 16, 'Fez também o rei Salomão duzentos paveses de ouro estendido: seiscentos siclos de ouro gastou em cada pavês.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 17, 'Também trezentos escudos de ouro estendido, em cada um dos quais gastou três libras de ouro: e os pôs o rei na casa do bosque do Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 18, 'Fez também o rei um grande trono de marfim, o qual cobriu de ouro puríssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 19, 'Seis degraus tinha o trono, e o alto dele era redondo pelo recosto: e da uma parte e da outra tinha apoios próximo do assento, junto aos quais estavam colocados dois leões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 20, 'Estavam também doze leões postos ali sobre os seis degraus, da uma parte e da outra: em nenhum outro reino se havia feito trono semelhante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 21, 'E todos os vasos de beber do rei Salomão eram de ouro, e também toda a vasilha da casa do bosque do Líbano era de ouro fino: não havia prata; em tempo de Salomão não era de valor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 22, 'Porque o rei tinha a frota que saía à mar, a Társis, com a frota de Hirão: uma vez em cada três anos vinha a frota de Társis, e trazia ouro, prata, marfim, macacos e pavões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 23, 'Assim excedia o rei Salomão a todos os reis da terra em riquezas e em sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 24, 'Toda a terra procurava ver a cara de Salomão, para ouvir sua sabedoria, a qual Deus havia posto em seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 25, 'E todos lhe levavam cada ano seus tributos: utensílios de ouro, utensílios de prata, roupas, armas, aromas, cavalos e mulas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 26, 'E juntou Salomão carros e cavaleiros; e tinha mil quatrocentos carros, e doze mil cavaleiros, os quais pôs nas cidades dos carros, e com o rei em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 27, 'E pôs o rei em Jerusalém prata como pedras, e cedros como os sicômoros que estão pelos campos em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 28, 'E traziam cavalos a Salomão do Egito e de Coa: porque os mercadores do rei compravam cavalos de Coa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 10, 29, 'E vinha e saía do Egito, o carro por seiscentas peças de prata, e o cavalo por cento e cinquenta; e assim os traziam por meio deles, todos os reis dos heteus, e da Síria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 1, 'Porém o rei Salomão amou, além da filha de Faraó, muitas mulheres estrangeiras: às de Moabe, às de Amom, às de Edom, às de Sidom, e às heteias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 2, 'Nações das quais o SENHOR havia dito aos filhos de Israel: Não entrareis a elas, nem elas entrarão a vós; porque certamente farão inclinar vossos corações atrás seus deuses. A estas, pois, juntou-se Salomão com amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 3, 'E teve setecentas esposas princesas, e trezentas concubinas; e suas mulheres desviaram o coração dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 4, 'E aconteceu que, na velhice de Salomão, suas mulheres inclinaram o seu coração para seguir outros deuses; e o coração dele não era completo com o SENHOR seu Deus, como o coração do seu pai Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 5, 'Porque Salomão seguiu Astarote, deusa dos sidônios, e a Milcom, abominação dos amonitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 6, 'E fez Salomão o que era mau aos olhos do SENHOR, e não seguiu completamente o SENHOR como o seu pai Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 7, 'Então edificou Salomão um alto a Camos, abominação de Moabe, no monte que está à frente de Jerusalém; e a Moloque, abominação dos filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 8, 'E assim fez para todas suas mulheres estrangeiras, as quais queimavam incenso, e sacrificavam aos seus deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 9, 'E o SENHOR se irou contra Salomão, pois o seu coração estava desviado do SENHOR Deus de Israel, que lhe havia aparecido duas vezes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 10, 'E lhe havia mandado acerca disto, que não seguisse outros deuses; mas ele não guardou o que o SENHOR havia lhe mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 11, 'E disse o SENHOR a Salomão: Como houve isso em ti, e não guardaste o meu pacto e os meus estatutos que eu te mandei, romperei o reino de ti, e o entregarei a teu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 12, 'Porém não o farei em teus dias, por amor de Davi teu pai; eu o romperei da mão de teu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 13, 'Todavia não romperei todo o reino, mas sim que darei uma tribo a teu filho, por amor de Davi meu servo, e por amor de Jerusalém que eu escolhi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 14, 'E o SENHOR suscitou um adversário a Salomão, a Hadade, edomita, do sangue real, o qual estava em Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 15, 'Porque quando Davi estava em Edom, e subiu Joabe o general do exército a enterrar os mortos, e matou a todos os homens de Edom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 16, '(Porque seis meses habitou ali Joabe, e todo Israel, até que havia acabado a todo o sexo masculino em Edom;)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 17, 'Então fugiu Hadade, e com ele alguns homens edomitas dos servos de seu pai, e foi-se ao Egito; era então Hadade jovem pequeno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 18, 'E levantaram-se de Midiã, e vieram a Parã; e tomando consigo homens de Parã, vieram-se ao Egito, a Faraó rei do Egito, o qual lhe deu casa, e lhe assinalou alimentos, e ainda lhe deu terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 19, 'E achou Hadade grande graça diante de Faraó, o qual lhe deu por mulher à irmã de sua esposa, à irmã da rainha Tafnes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 20, 'E a irmã de Tafnes lhe deu à luz seu filho Genubate, ao qual Tafnes desmamou dentro da casa de Faraó; e estava Genubate na casa de Faraó entre os filhos de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 21, 'E ouvindo Hadade em Egito que Davi havia dormido com seus pais, e que era morto Joabe general do exército, Hadade disse a Faraó: Deixa-me ir a minha terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 22, 'E respondeu-lhe Faraó: Por que? O que te falta comigo, que procuras ir-te a tua terra? E ele respondeu: Nada; contudo, rogo-te que me deixes ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 23, 'Despertou-lhe também Deus por adversário a Rezom, filho de Eliada, o qual havia fugído de seu amo Hadadezer, rei de Zobá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 24, 'E havia juntado gente contra ele, e havia-se feito capitão de uma companhia, quando Davi derrotou aos de Zobá. Depois se foram a Damasco, e habitaram ali e fizeram-lhe rei em Damasco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 25, 'E foi adversário a Israel todos os dias de Salomão; e foi outro mal com o de Hadade, porque aborreceu a Israel, e reinou sobre a Síria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 26, 'Também Jeroboão filho de Nebate, efrateu de Zeredá, servo de Salomão, (sua mãe se chamava Zerua, mulher viúva) levantou sua mão contra o rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 27, 'E a causa por que este levantou mão contra o rei, foi esta: Salomão edificando a Milo, fechou a abertura da cidade de Davi seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 28, 'E o homem Jeroboão era valente e esforçado; e vendo Salomão ao rapaz que era homem ativo, encomendou-lhe todo o cargo da casa de José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 29, 'Aconteceu pois naquele tempo, que saindo Jeroboão de Jerusalém, encontrou-lhe no caminho o profeta Aías silonita; e ele estava coberto com uma capa nova; e estavam eles dois sós no campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 30, 'E segurando Aías da capa nova que tinha sobre si, rompeu-a em doze pedaços,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 31, 'E disse a Jeroboão: Toma para ti os dez pedaços; porque assim disse o SENHOR Deus de Israel: Eis que que eu rompo o reino da mão de Salomão, e a ti darei dez tribos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 32, '(E ele terá uma tribo, por amor de Davi meu servo, e por amor de Jerusalém, cidade que eu escolhi de todas as tribos de Israel:)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 33, 'Porquanto me deixaram, e adoraram a Astarote deusa dos sidônios, e a Camos deus de Moabe, e a Moloque deus dos filhos de Amom; e não andaram em meus caminhos, para fazer o reto diante de meus olhos, e meus estatutos, e meus direitos, como fez seu pai Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 34, 'Porém não tirarei nada de seu reino de suas mãos, mas sim que o manterei por chefe todos os dias de sua vida, por amor de Davi meu servo, ao qual eu escolhi, e ele guardou meus mandamentos e meus estatutos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 35, 'Mas eu tirarei o reino da mão de seu filho, e o darei a ti, as dez tribos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 36, 'E a seu filho darei uma tribo, para que meu servo Davi tenha lâmpada todos os dias diante de mim em Jerusalém, cidade que eu me escolhi para pôr nela meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 37, 'Eu pois te tomarei a ti, e tu reinarás em todas as coisas que desejar tua alma, e serás rei sobre Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 38, 'E será que, se prestares ouvido a todas as coisas que te mandar, e andares em meus caminhos, e fizeres o reto diante de meus olhos, guardando meus estatutos e meus mandamentos, como fez Davi meu servo, eu serei contigo, e te edificarei casa firme, como a edifiquei a Davi, e eu te entregarei a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 39, 'E eu afligirei a semente de Davi por causa disto, mas não para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 40, 'Procurou, portanto, Salomão de matar a Jeroboão, mas levantando-se Jeroboão, fugiu ao Egito, a Sisaque rei do Egito, e esteve em Egito até a morte de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 41, 'Os demais dos feitos de Salomão, e todas as coisas que fez, e sua sabedoria, não estão escritas no livro dos feitos de Salomão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 42, 'E os dias que Salomão reinou em Jerusalém sobre todo Israel foram quarenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 11, 43, 'E descansou Salomão com seus pais, e foi sepultado na cidade de seu pai Davi: e reinou em seu lugar Roboão seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 1, 'E foi Roboão a Siquém; porque todo Israel havia vindo a Siquém para fazê-lo rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 2, 'E aconteceu, que quando o ouviu Jeroboão filho de Nebate, que estava em Egito, porque havia fugido de diante do rei Salomão, e habitava em Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 3, 'Enviaram e chamaram-lhe. Veio pois Jeroboão e toda a congregação de Israel, e falaram a Roboão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 4, 'Teu pai agravou nosso jugo, mas agora tu diminui algo da dura servidão de teu pai, e do jugo pesado que ele pôs sobre nós, e te serviremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 5, 'E ele lhes disse: Ide, e daqui a três dias voltai a mim. E o povo se foi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 6, 'Então o rei Roboão tomou conselho com os anciãos que haviam estado diante de Salomão seu pai quando vivia, e disse: Como aconselhais vós que responda a este povo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 7, 'E eles lhe falaram, dizendo: Se tu fores hoje servo deste povo, e o servires, e respondendo-lhe boas palavras lhes falares, eles te servirão para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 8, 'Mas ele, deixado o conselho dos anciãos que eles lhe haviam dado, tomou conselho com os rapazes que se haviam criado com ele, e estavam diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 9, 'E disse-lhes: Como aconselhais vós que respondamos a este povo, que me falou, dizendo: Diminui algo do jugo que teu pai pôs sobre nós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 10, 'Então os rapazes que se haviam criado com ele lhe responderam, dizendo: Assim falarás a este povo que te disse estas palavras: Teu pai agravou nosso jugo; mas tu diminui-nos algo: assim lhes falarás: O menor dedo dos meus é mais espesso que os lombos de meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 11, 'Agora, pois, meu pai vos impôs carga de pesado jugo, mas eu acrescentarei a vosso jugo; meu pai vos feriu com açoites, mas eu vos ferirei com escorpiões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 12, 'E ao terceiro dia veio Jeroboão com todo o povo a Roboão; segundo o rei o havia mandado, dizendo: Voltai a mim ao terceiro dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 13, 'E o rei respondeu ao povo duramente, deixado o conselho dos anciãos que eles lhe haviam dado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 14, 'E falou-lhes conforme ao conselho dos rapazes, dizendo: Meu pai agravou vosso jugo, mas eu acrescentarei a vosso jugo; meu pai vos feriu com açoites, mas eu vos ferirei com escorpiões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 15, 'E não ouviu o rei ao povo; porque era ordenação do SENHOR, para confirmar sua palavra, que o SENHOR havia falado por meio de Aías silonita a Jeroboão filho de Nebate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 16, 'E quando todo o povo viu que o rei não lhes havia ouvido, respondeu-lhe estas palavras, dizendo: Que parte temos nós com Davi? Não temos propriedade no filho de Jessé. Israel, a tuas moradas! Provê agora em tua casa, Davi! Então Israel se foi a suas moradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 17, 'Mas reinou Roboão sobre os filhos de Israel que moravam nas cidades de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 18, 'E o rei Roboão enviou a Adorão, que estava sobre os tributos; mas apedrejou-lhe todo Israel, e morreu. Então o rei Roboão se esforçou a subir em um carro, e fugir a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 19, 'Assim se separou Israel da casa de Davi até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 20, 'E aconteceu que, ouvindo todo Israel que Jeroboão havia voltado, enviaram e chamaram-lhe à congregação, e fizeram-lhe rei sobre todo Israel, sem restar tribo alguma que seguisse a casa de Davi, a não ser somente a tribo de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 21, 'E quando Roboão veio a Jerusalém, juntou toda a casa de Judá e a tribo de Benjamim, cento e oitenta mil homens escolhidos de guerra, para fazer guerra à casa de Israel, e restituir o reino a Roboão filho de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 22, 'Mas foi palavra do SENHOR a Semaías homem de Deus, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 23, 'Fala a Roboão filho de Salomão, rei de Judá, e a toda a casa de Judá e de Benjamim, e aos demais do povo, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 24, 'Assim disse o SENHOR: Não vades, nem luteis contra vossos irmãos os filhos de Israel; voltai-vos cada um à sua casa; porque este negócio eu o fiz. E eles ouviram a palavra de Deus, e voltaram, e foram-se, conforme à palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 25, 'E reedificou Jeroboão a Siquém no monte de Efraim, e habitou nela; e saindo dali, reedificou a Peniel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 26, 'E disse Jeroboão em seu coração: Agora se voltará o reino à casa de Davi,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 27, 'Se este povo subir a sacrificar à casa do SENHOR em Jerusalém: porque o coração deste povo se converterá a seu senhor Roboão rei de Judá, e me matarão a mim, e se tornarão a Roboão rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 28, 'E havido conselho, fez o rei dois bezerros de ouro, e disse ao povo: Demais subistes a Jerusalém: eis que teus deuses, ó Israel, que te fizeram subir da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 29, 'E pôs o um em Betel, e o outro pôs em Dã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 30, 'E isto foi ocasião de pecado; porque o povo ia a adorar diante do um, até Dã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 31, 'Fez também casa de altos, e fez sacerdotes da classe do povo, que não eram dos filhos de Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 32, 'Então instituiu Jeroboão solenidade no mês oitavo, aos quinze do mês, conforme à solenidade que se celebrava em Judá; e sacrificou sobre altar. Assim fez em Betel, sacrificando aos bezerros que havia feito. Ordenou também em Betel sacerdote'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 12, 33, 'Sacrificou pois sobre o altar que ele havia feito em Betel, aos quinze do mês oitavo, o mês que ele havia inventado de seu coração; e fez festa aos filhos de Israel, e subiu ao altar para queimar incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 1, 'E eis que um homem de Deus por palavra do SENHOR veio de Judá a Betel; e estando Jeroboão ao altar para queimar incenso,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 2, 'Ele clamou contra o altar por palavra do SENHOR, e disse: Altar, altar, assim disse o SENHOR: Eis que à casa de Davi nascerá um filho, chamado Josias, o qual sacrificará sobre ti aos sacerdotes dos altos que queimam sobre ti incenso; e sobre ti queimarão ossos humanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 3, 'E aquele mesmo dia deu um sinal, dizendo: Esta é o sinal de que o SENHOR falou: eis que que o altar se quebrará, e a cinza que sobre ele está se derramará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 4, 'E quando o rei Jeroboão ouviu a palavra do homem de Deus, que havia clamado contra o altar de Betel, estendendo sua mão desde o altar, disse: Prendei-lhe! Mas a mão que havia estendido contra ele, se lhe secou, que não a pôde voltar a si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 5, 'E o altar se rompeu, e derramou-se a cinza do altar, conforme o sinal que o homem de Deus havia dado por palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 6, 'Então respondendo o rei, disse ao homem de Deus: Peço-te que rogues à face do SENHOR teu Deus, e ora por mim, que minha mão me seja restituída. E o homem de Deus orou à face do SENHOR, e a mão do rei se lhe recuperou e tornou-se como antes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 7, 'E o rei disse ao homem de Deus: Vem comigo à casa, e comerás, e eu te darei um presente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 8, 'Mas o homem de Deus disse ao rei: Se me desses a metade de tua casa, não iria contigo, nem comeria pão nem beberia água neste lugar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 9, 'Porque assim me está mandado por palavra do SENHOR, dizendo: Não comas pão, nem bebas água, nem voltes pelo caminho que fordes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 10, 'Foi-se, pois, por outro caminho, e não voltou pelo caminho por de onde havia vindo a Betel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 11, 'Morava naquele tempo em Betel um velho profeta, ao qual veio seu filho, e contou-lhe tudo o que o homem de Deus havia feito aquele dia em Betel: contaram-lhe também a seu pai as palavras que havia falado ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 12, 'E seu pai lhes disse: Por que caminho foi? E seus filhos lhe mostraram o caminho por de onde se havia voltado o homem de Deus, que havia vindo de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 13, 'E ele disse a seus filhos: Preparai-me o asno. E eles lhe prepararam o asno, e subiu nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 14, 'E indo atrás o homem de Deus, achou-lhe que estava sentado debaixo de um carvalho: e disse-lhe: És tu o homem de Deus que vieste de Judá? E ele disse: Eu sou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 15, 'Disse-lhe então: Vem comigo à casa, e come do pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 16, 'Mas ele respondeu: Não poderei voltar contigo, nem irei contigo; nem tampouco comerei pão nem beberei água contigo neste lugar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 17, 'Porque por palavra de Deus me foi dito: Não comas pão nem bebas água ali, nem voltes pelo caminho que fores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 18, 'E o outro lhe disse: Eu também sou profeta como tu, e um anjo me falou pela palavra do SENHOR, dizendo: Faze-o voltar contigo à tua casa, para que coma pão e beba água. Porém mentiu-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 19, 'Então voltou com ele, e comeu do pão em sua casa, e bebeu da água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 20, 'E aconteceu que, estando eles à mesa, veio a palavra do SENHOR ao profeta que lhe havia feito voltar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 21, 'E clamou ao homem de Deus que havia vindo de Judá, dizendo: Assim disse o SENHOR: Porquanto foste rebelde ao dito do SENHOR, e não guardaste o mandamento que o SENHOR teu Deus te havia prescrito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 22, 'Em vez disso voltaste, e comeste do pão e bebeste da água no lugar de onde o SENHOR te havia dito não comesses pão nem bebesses água, não entrará teu corpo no sepulcro de teus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 23, 'E quando havia comido do pão e bebido, o profeta que lhe havia feito voltar lhe preparou um asno;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 24, 'E indo-se, encontrou-lhe um leão no caminho, e matou-lhe; e seu corpo estava lançado no caminho, e o asno estava junto a ele, e o leão também estava junto ao corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 25, 'E eis que uns que passavam, e viram o corpo que estava lançado no caminho, e o leão que estava junto ao corpo: e vieram, e disseram-no na cidade de onde o velho profeta habitava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 26, 'E ouvindo-o o profeta que lhe havia voltado do caminho, disse: O homem de Deus é, que foi rebelde ao dito do SENHOR: portanto o SENHOR lhe entregou ao leão, que lhe quebrantou e matou, conforme à palavra do SENHOR que ele lhe disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 27, 'E falou a seus filhos, e disse-lhes: Preparai-me um asno. E eles se o prepararam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 28, 'E ele foi, e achou seu corpo estendido no caminho, e o asno e o leão estavam junto ao corpo: o leão não havia comido o corpo, nem danificado ao asno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 29, 'E tomando o profeta o corpo do homem de Deus, o pôs sobre o asno, e o levou. E o profeta velho veio à cidade, para lamentar-lhe e enterrar-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 30, 'E pôs seu corpo em seu sepulcro; e lamentaram-lhe, dizendo: Ai, irmão meu!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 31, 'E depois que lhe houveram enterrado, falou a seus filhos, dizendo: Quando eu morrer, enterrai-me no sepulcro em que está sepultado o homem de Deus; ponde meus ossos junto aos seus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 32, 'Porque sem dúvida virá o que ele disse a vozes por palavra do SENHOR contra o altar que está em Betel, e contra todas as casas dos altos que estão nas cidades de Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 33, 'Depois disto não se converteu Jeroboão de seu mau caminho: antes voltou a fazer sacerdotes dos altos da classe do povo, e quem queria se consagrava, e era dos sacerdotes dos altos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 13, 34, 'E isto foi causa de pecado à casa de Jeroboão; pelo qual foi cortada e desraigada de sobre a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 1, 'Naquele tempo Abias filho de Jeroboão caiu enfermo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 2, 'E disse Jeroboão à sua mulher: Levanta-te agora, disfarça-te, porque não te conheçam que és a mulher de Jeroboão, e vai a Siló; que ali está Aías profeta, o que me disse que eu havia de ser rei sobre este povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 3, 'E toma em tua mão dez pães, e bolos, e uma botija de mel, e vai a ele; que te declare o que será deste jovem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 4, 'E a mulher de Jeroboão o fez assim; e levantou-se, e foi a Siló, e veio à casa de Aías. E não podia já ver Aías, que seus olhos se haviam escurecido à causa de sua velhice.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 5, 'Mas o SENHOR havia dito a Aías: Eis que a mulher de Jeroboão virá a consultar-te por seu filho, que está enfermo: assim e assim lhe responderás; pois será que quando ela vier, virá dissimulada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 6, 'E quando Aías ouviu o som de seus pés quando entrava pela porta, disse: Entra, mulher de Jeroboão; por que te finges outra? Porém eu sou enviado a ti com revelação dura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 7, 'Vai, e dize a Jeroboão: Assim disse o SENHOR Deus de Israel: Porquanto eu te levantei de em meio do povo, e te fiz príncipe sobre meu povo Israel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 8, 'E rompi o reino da casa de Davi, e o entreguei a ti; e tu não foste como Davi meu servo, que guardou meus mandamentos e andou após o mim com todo seu coração, fazendo somente o direito diante de meus olhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 9, 'Antes fizeste o mau sobre todos os que foram antes de ti: que foste e te fizeste deuses alheios e de fundição para irar-me, e a mim me lançaste atrás tuas costas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 10, 'Portanto, eis que eu trago mal sobre a casa de Jeroboão, e eu exterminarei de Jeroboão todo macho, tanto o escravo como o livre em Israel; e varrerei a posteridade da casa de Jeroboão, como é varrido o lixo, até que seja acabada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 11, 'O que morrer dos de Jeroboão na cidade, lhe comerão os cães; e o que morrer no campo, as aves do céu o comerão; porque o SENHOR o disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 12, 'E tu levanta-te, e vai-te à tua casa; que em entrando teu pé na cidade, morrerá o jovem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 13, 'E todo Israel o lamentará, e lhe enterrarão; porque somente ele dos de Jeroboão entrará em sepultura; porquanto se achou nele alguma coisa boa do SENHOR Deus de Israel, na casa de Jeroboão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 14, 'E o SENHOR se levantará um rei sobre Israel, o qual exterminará a casa de Jeroboão neste dia; e que, se agora?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 15, 'E o SENHOR sacudirá a Israel, ao modo que a cana se agita nas águas: e ele arrancará a Israel desta boa terra que havia dado a seus pais, e os dispersará da outra parte do rio, porquanto fizeram seus bosques, irando ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 16, 'E ele entregará a Israel pelos pecados de Jeroboão, o qual pecou, e fez pecar a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 17, 'Então a mulher de Jeroboão se levantou, e se foi, e veio a Tirsa: e entrando ela pelo umbral da casa, o jovem morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 18, 'E enterraram-no, e lamentaram-no todo Israel, conforme à palavra do SENHOR, que ele havia falado por mão de seu servo Aías profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 19, 'Os outros feitos de Jeroboão, que guerras fez, e como reinou, tudo está escrito no livro das histórias dos reis de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 20, 'O tempo que reinou Jeroboão foram vinte e dois anos; e havendo descansado com seus pais, reinou em seu lugar Nadabe seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 21, 'E Roboão filho de Salomão reinou em Judá. De quarenta e um anos era Roboão quando começou a reinar, e dezessete anos reinou em Jerusalém, cidade que o SENHOR elegeu de todas as tribos de Israel para pôr ali seu nome. O nome de sua mãe foi Naamá, amonita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 22, 'E Judá fez o que era mau aos olhos do SENHOR, e iraram-lhe mais que tudo o que seus pais haviam feito em seus pecados que cometeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 23, 'Porque eles também se edificaram altos, estátuas, e bosques, em todo morro alto, e debaixo de toda árvore frondosa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 24, 'E havia também sodomitas na terra, e fizeram conforme a todas as abominações das nações que o SENHOR havia lançado diante dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 25, 'Ao quinto ano do rei Roboão subiu Sisaque rei do Egito contra Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 26, 'E tomou os tesouros da casa do SENHOR, e os tesouros da casa real, e saqueou-o tudo: levou-se também todos os escudos de ouro que Salomão havia feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 27, 'E em lugar deles fez o rei Roboão escudos de bronze, e deu-os em mãos dos capitães dos da guarda, os quais guardavam a porta da casa real.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 28, 'E quando o rei entrava na casa do SENHOR, os da guarda os levavam; e punham-nos depois na câmara dos da guarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 29, 'Os demais dos feitos de Roboão, e todas as coisas que fez, não estão escritas nas crônicas dos reis de Judá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 30, 'E havia guerra entre Roboão e Jeroboão todos os dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 14, 31, 'E descansou Roboão com seus pais, e foi sepultado com seus pais na cidade de Davi. O nome de sua mãe foi Naamá, amonita. E reinou em seu lugar Abião seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 1, 'No ano dezoito do rei Jeroboão filho de Nebate, Abião começou a reinar sobre Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 2, 'Reinou três anos em Jerusalém. O nome de sua mãe era Maaca, filha de Absalão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 3, 'E andou em todos os pecados de seu pai, que havia este feito antes dele; e não foi seu coração completo com o SENHOR seu Deus, como o coração do seu pai Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 4, 'Mas por amor de Davi, deu-lhe o SENHOR seu Deus lâmpada em Jerusalém, levantando-lhe a seu filho depois dele, e sustentando a Jerusalém:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 5, 'Porquanto Davi havia feito o que era correto diante dos olhos do SENHOR, e de nenhuma coisa que lhe mandasse se havia apartado em todos os dias de sua vida, exceto o negócio de Urias Heteu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 6, 'E havia guerra entre Roboão e Jeroboão todos os dias de sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 7, 'Os demais dos feitos de Abião, e todas as coisas que fez, não estão escritas no livro das crônicas dos reis de Judá? E havia guerra entre Abião e Jeroboão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 8, 'E dormiu Abião com seus pais, e sepultaram-no na cidade de Davi: e reinou Asa seu filho em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 9, 'No ano vinte de Jeroboão rei de Israel, Asa começou a reinar sobre Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 10, 'E reinou quarenta e um anos em Jerusalém; o nome de sua avó era Maaca, filha de Absalão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 11, 'E Asa fez o que era correto diante dos olhos do SENHOR, como o seu pai Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 12, 'Porque tirou os sodomitas da terra, e tirou todas as imundícies que seus pais haviam feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 13, 'E também tirou de sua avó Maaca a posição de rainha-mãe, porque havia feito um ídolo num bosque. Além disso, Asa destruiu o ídolo dela, e o queimou junto ao ribeiro de Cedrom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 14, 'Porém os altos não foram tirados. Contudo, o coração de Asa foi completo com o SENHOR durante toda a sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 15, 'Também trouxe à casa do SENHOR o que o seu pai havia dedicado, e o que ele dedicou: ouro, e prata, e utensílios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 16, 'E havia guerra entre Asa e Baasa, rei de Israel, durante todo o tempo deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 17, 'E Baasa, rei de Israel, subiu contra Judá, e edificou Ramá, para não deixar sair nem entrar a ninguém de Asa, rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 18, 'Então Asa tomou toda a prata e ouro que havia restado nos tesouros da casa do SENHOR, e os tesouros da casa real, entregou-os nas mãos de seus servos, e o rei Asa os enviou a Ben-Hadade, filho de Tabrimom, filho de Heziom, rei da Síria, o qual residia em Damasco, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 19, '[Haja] uma aliança entre mim e ti, entre meu pai e o teu pai; eis que eu te envio um presente de prata e ouro. Vai, e rompe a tua aliança com Baasa, rei de Israel, para que me deixe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 20, 'E Ben-Hadade consentiu com o rei Asa, e enviou os príncipes dos exércitos que tinha contra as cidades de Israel, e feriu a Ijom, e a Dã, e a Abel-Bete-Maaca, e a toda Quinerete, com toda a terra de Naftali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 21, 'E ouvindo isto Baasa, deixou de edificar a Ramá, e ficou em Tirsa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 22, 'Então o rei Asa convocou a todo Judá, sem excetuar ninguém; e tiraram de Ramá a pedra e a madeira com que Baasa edificava, e edificou o rei Asa com ele a Gibeá de Benjamim, e a Mispá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 23, 'Os demais de todos os feitos de Asa, e toda sua fortaleza, e todas as coisas que fez, e as cidades que edificou, não está tudo escrito no livro das crônicas dos reis de Judá? Mas no tempo de sua velhice enfermou de seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 24, 'E descansou Asa com seus pais, e foi sepultado com seus pais na cidade de Davi seu pai: e reinou em seu lugar Josafá seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 25, 'E Nadabe, filho de Jeroboão, começou a reinar sobre Israel no segundo ano de Asa rei de Judá; e reinou sobre Israel dois anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 26, 'E fez o que era mau diante dos olhos do SENHOR, andando no caminho de seu pai, e em seus pecados com que fez pecar a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 27, 'E Baasa filho de Aías, o qual era da casa de Issacar, fez conspiração contra ele: e feriu-o Baasa em Gibetom, que era dos filisteus: porque Nadabe e todo Israel tinham cercado a Gibetom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 28, 'Matou-o, pois, Baasa no terceiro ano de Asa rei de Judá, e reinou em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 29, 'E quando ele veio ao reino, feriu toda a casa de Jeroboão, sem deixar alma vivente dos de Jeroboão, até exterminá-lo, conforme à palavra do SENHOR que ele falou por seu servo Aías silonita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 30, 'Por causa dos pecados de Jeroboão que ele havia cometido, e com os quais fez pecar a Israel; e por sua provocação com que provocou à ira ao SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 31, 'Os demais dos feitos de Nadabe, e todas as coisas que fez, não está tudo escrito no livro das crônicas dos reis de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 32, 'E havia guerra entre Asa e Baasa, rei de Israel, durante todo o tempo deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 33, 'No terceiro ano de Asa, rei de Judá, começou a reinar Baasa, filho de Aías, sobre todo Israel em Tirsa; e reinou vinte e quatro anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 15, 34, 'E fez o que era mau aos olhos do SENHOR, e andou no caminho de Jeroboão, e em seu pecado com que fez pecar a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 1, 'E foi palavra do SENHOR a Jeú, filho de Hanani, contra Baasa, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 2, 'Posto que te levantei do pó, e te pus por príncipe sobre meu povo Israel, e andaste no caminho de Jeroboão, e fizeste pecar a meu povo Israel, provocando-me à ira com os seus pecados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 3, 'Eis que varrerei a posteridade de Baasa, e a posteridade de sua casa; e tornarei a tua casa como a casa de Jeroboão, filho de Nebate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 4, 'O que de Baasa for morto na cidade, os cães lhe comerão; e o que dele for morto no campo, as aves do céu o comerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 5, 'Os demais dos feitos de Baasa, e as coisas que fez, e sua fortaleza, não está tudo escrito no livro das crônicas dos reis de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 6, 'E descansou Baasa com seus pais, e foi sepultado em Tirsa; e reinou em seu lugar Elá, seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 7, 'Porém a palavra do SENHOR por meio de Jeú profeta, filho de Hanani, havia sido contra Baasa e também contra sua casa, com motivo de todo o mal que fez aos olhos do SENHOR, provocando-lhe à ira com as obras de suas mãos, para que fosse feita como a casa de Jeroboão; e porque o havia ferido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 8, 'No ano vinte e seis de Asa rei de Judá, começou a reinar Elá filho de Baasa sobre Israel em Tirsa; e reinou dois anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 9, 'E fez conspiração contra ele seu servo Zinri, comandante da metade dos carros. E estando ele em Tirsa, bebendo e embriagado em casa de Arsa seu mordomo em Tirsa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 10, 'Veio Zinri, e o feriu e matou, no ano vinte e sete de Asa rei de Judá; e reinou em lugar seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 11, 'E logo que chegou a reinar e esteve sentado em seu trono, feriu toda a casa de Baasa, sem deixar nela macho, nem seus parentes nem amigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 12, 'Assim exterminou Zinri toda a casa de Baasa, conforme à palavra do SENHOR, que havia proferido contra Baasa por meio do profeta Jeú;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 13, 'Por todos os pecados de Baasa, e os pecados de Elá seu filho, com que eles pecaram e fizeram pecar a Israel, provocando à ira ao SENHOR Deus de Israel com suas vaidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 14, 'Os demais feitos de Elá, e todas as coisas que fez, não está tudo escrito no livro das crônicas dos reis de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 15, 'No ano vinte e sete de Asa rei de Judá, começou a reinar Zinri, e reinou sete dias em Tirsa; e o povo havia assentado campo sobre Gibetom, cidade dos filisteus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 16, 'E o povo que estava no campo ouviu dizer: Zinri fez conspiração, e matou ao rei. Então todo Israel levantou o mesmo dia por rei sobre Israel a Onri, general do exército, no campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 17, 'E subiu Onri de Gibetom, e com ele todo Israel, e cercaram a Tirsa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 18, 'Mas vendo Zinri tomado a cidade, entrou no palácio da casa real, e pegou fogo à casa consigo: assim morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 19, 'Por seus pecados que ele havia cometido, fazendo o que era mau aos olhos do SENHOR, e andando nos caminhos de Jeroboão, e em seu pecado que cometeu, fazendo pecar a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 20, 'Os demais feitos de Zinri, e sua conspiração que formou, não está tudo escrito no livro das crônicas dos reis de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 21, 'Então o povo de Israel foi dividido em duas partes: a metade do povo seguia a Tibni filho de Ginate, para fazê-lo rei: e a outra metade seguia a Onri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 22, 'Mas o povo que seguia a Onri pôde mais que o que seguia a Tibni filho de Ginate; e Tibni morreu, e Onri foi rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 23, 'No ano trinta e um de Asa rei de Judá, começou a reinar Onri sobre Israel, e reinou doze anos: em Tirsa reinou seis anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 24, 'E ele comprou de Semer o monte de Samaria por dois talentos de prata, e edificou no monte: e chamou o nome da cidade que edificou Samaria, do nome de Semer, senhor que foi daquele monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 25, 'E Onri fez o mau aos olhos do SENHOR, e fez pior que todos os que haviam sido antes dele:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 26, 'Pois andou em todos os caminhos de Jeroboão filho de Nebate, e em seu pecado com que fez pecar a Israel, provocando à ira ao SENHOR Deus de Israel com seus ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 27, 'Os demais dos feitos de Onri, e todas as coisas que fez, e suas valentias que executou, não está tudo escrito no livro das crônicas dos reis de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 28, 'E Onri descansou com seus pais, e foi sepultado em Samaria; e reinou em lugar seu Acabe, seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 29, 'E começou a reinar Acabe filho de Onri sobre Israel o ano trinta e oito de Asa rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 30, 'E reinou Acabe filho de Onri sobre Israel em Samaria vinte e dois anos. E Acabe filho de Onri fez o que era mau aos olhos do SENHOR além de todos os que foram antes dele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 31, 'Porque lhe foi pouca coisa andar nos pecados de Jeroboão filho de Nebate, e tomou por mulher a Jezabel filha de Etbaal rei dos sidônios, e foi e serviu a Baal, e o adorou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 32, 'E fez altar a Baal, no templo de Baal que ele edificou em Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 33, 'Fez também Acabe um bosque; e acrescentou Acabe fazendo provocar à ira ao SENHOR Deus de Israel, mais que todos os reis de Israel que antes dele haviam sido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 16, 34, 'Em seu tempo Hiel de Betel reedificou a Jericó. À custa de Abirão seu primogênito lançou o alicerce, e à custa de Segube seu filho posterior pôs suas portas, conforme à palavra do SENHOR que havia falado por Josué filho de Num.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 1, 'Então Elias Tisbita, que era dos moradores de Gileade, disse a Acabe: Vive o SENHOR Deus de Israel, diante do qual estou, que não haverá chuva nem orvalho nestes anos, a não ser por minha palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 2, 'E foi a ele palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 3, 'Aparta-te daqui, e volta-te ao oriente, e esconde-te no ribeiro de Querite, que está diante do Jordão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 4, 'E beberás do ribeiro; e eu ei mandado aos corvos que te deem ali de comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 5, 'E ele foi, e fez conforme à palavra do SENHOR; pois se foi e assentou junto ao ribeiro de Querite, que está antes do Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 6, 'E os corvos lhe traziam pão e carne pela manhã, e pão e carne à tarde; e bebia do ribeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 7, 'Passados alguns dias, secou-se o ribeiro; porque não havia chovido sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 8, 'E foi a ele palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 9, 'Levanta-te, vai-te a Sarepta de Sidom, e ali morarás: eis que eu mandei ali a uma mulher viúva que te sustente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 10, 'Então ele se levantou, e se foi a Sarepta. E quando chegou à porta da cidade, eis que uma mulher viúva que estava ali colhendo gravetos; e ele a chamou, e disse-lhe: Rogo-te que me tragas um pouco de água em um vaso, para que beba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 11, 'E indo ela para trazê-la, ele a voltou a chamar, e disse-lhe: Rogo-te que me tragas também um bocado de pão em tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 12, 'E ela respondeu: Vive o SENHOR Deus teu, que não tenho pão cozido; que somente um punhado de farinha tenho no jarro, e um pouco de azeite em uma botija: e agora cozia dois gravetos, para entrar-me e prepará-lo para mim e para meu filho, e que o comamos, e morramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 13, 'E Elias lhe disse: Não tenhas temor; vai, face como disseste: porém faze-me a mim primeiro disso uma pequena torta cozida debaixo da cinza, e traze-a a mim; e depois farás para ti e para teu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 14, 'Porque o SENHOR Deus de Israel disse assim: O jarro da farinha não esvaziará, nem se diminuirá a botija do azeite, até aquele dia que o SENHOR dará chuva sobre a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 15, 'Então ela foi, e fez como lhe disse Elias; e comeu ele, e ela e sua casa, muitos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 16, 'E o jarro da farinha não esvaziou, nem minguou a botija do azeite, conforme à palavra do SENHOR que havia dito por Elias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 17, 'Depois destas coisas aconteceu que caiu enfermo o filho da ama da casa, e a enfermidade foi tão grave, que não restou nele respiração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 18, 'E ela disse a Elias: Que tenho eu contigo, homem de Deus? Vieste a mim para trazer em memória minhas iniquidades, e para fazer-me morrer meu filho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 19, 'E ele lhe disse: Dá-me aqui teu filho. Então ele o tomou de seu colo, e levou-o à câmara de onde ele estava, e pôs-lhe sobre sua cama;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 20, 'E clamando ao SENHOR, disse: SENHOR Deus meu, ainda à viúva em cuja casa eu estou hospedado afligiste, matando-lhe seu filho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 21, 'E ele se estendeu sobre o menino três vezes, e clamou ao SENHOR, e disse: SENHOR Deus meu, rogo-te que volte a alma deste menino a suas entranhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 22, 'E o SENHOR ouviu a voz de Elias, e a alma do menino voltou a suas entranhas, e reviveu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 23, 'Tomando logo Elias ao menino, trouxe-o da câmara à casa, e deu-o à sua mãe, e disse-lhe Elias: Olha, teu filho vive.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 17, 24, 'Então a mulher disse a Elias: Agora conheço que tu és homem de Deus, e que a palavra do SENHOR é verdade em tua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 1, 'Passados muitos dias, veio a palavra do SENHOR a Elias no terceiro ano, dizendo: Vai, mostra-te a Acabe, e eu darei chuva sobre a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 2, 'Foi, pois, Elias a mostrar-se a Acabe. Havia naquele tempo grande fome em Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 3, 'E Acabe chamou a Obadias seu mordomo, o qual Obadias era em grande maneira temeroso do SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 4, 'Porque quando Jezabel destruía aos profetas do SENHOR, Obadias tomou cem profetas, os quais escondeu de cinquenta em cinquenta por covas, e sustentou-os a pão e água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 5, 'E disse Acabe a Obadias: Vai pela terra a todas as fontes de águas, e a todos os ribeiros; que acaso acharemos grama com que conservemos a vida aos cavalos e às mulas, para que não nos fiquemos sem animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 6, 'E repartiram entre si a terra para percorrerem-na; Acabe foi por si só por um caminho, e Obadias foi separadamente por outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 7, 'E indo Obadias pelo caminho, encontrou-se com Elias; e como lhe conheceu, prostrou-se sobre seu rosto, e disse: Não és tu meu senhor Elias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 8, 'E ele respondeu: Eu sou; vai, dize a teu amo: Eis que Elias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 9, 'Porém ele disse: Em que ei pecado, para que tu entregues teu servo em mão de Acabe para que me mate?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 10, 'Vive o SENHOR teu Deus, que não houve nação nem reino de onde meu senhor não haja enviado a buscar-te; e respondendo eles: Não está aqui, ele conjurou a reinos e nações se não te acharam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 11, 'E agora tu dizes: Vai, dize a teu amo: Aqui está Elias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 12, 'E acontecerá que, logo que eu me haja partido de ti, o espírito do SENHOR te levará de onde eu não saiba; e vindo eu, e dando as novas a Acabe, e se ele não te achar, me matará; e teu servo teme ao SENHOR desde sua juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 13, 'Não foi dito a meu senhor o que fiz, quando Jezabel matava aos profetas do SENHOR: que escondi cem homens dos profetas do SENHOR de cinquenta em cinquenta em covas, e os mantive a pão e água?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 14, 'E agora dizes tu: Vai, dize a teu amo: Aqui está Elias: para que ele me mate?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 15, 'E disse-lhe Elias: Vive o SENHOR dos exércitos, diante do qual estou, que hoje me mostrarei a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 16, 'Então Obadias foi a encontrar-se com Acabe, e deu-lhe o aviso; e Acabe veio a encontrar-se com Elias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 17, 'E quando Acabe viu a Elias, disse-lhe Acabe: És tu o que perturbas a Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 18, 'E ele respondeu: Eu não perturbei a Israel, mas sim tu e a casa de teu pai, deixando os mandamentos do SENHOR, e seguindo aos baalins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 19, 'Envia, pois, agora e juntai-me a todo Israel no monte de Carmelo, e os quatrocentos e cinquenta profetas de Baal, e os quatrocentos profetas dos bosques, que comem da mesa de Jezabel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 20, 'Então Acabe enviou a todos os filhos de Israel, e juntou os profetas no monte de Carmelo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 21, 'E aproximando-se Elias a todo o povo, disse: Até quando hesitareis vós entre dois pensamentos? Se o SENHOR é Deus, segui-lhe; e se Baal, ide depois dele. E o povo não respondeu palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 22, 'E Elias converteu a dizer ao povo: Só eu restei profeta do SENHOR; mas dos profetas de Baal há quatrocentos e cinquenta homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 23, 'Deem-se a nós, pois, dois bois, e escolham-se eles o um, e cortem-no em pedaços, e ponham-no sobre lenha, mas não ponham fogo debaixo; e eu prepararei o outro boi, e o porei sobre lenha, e nenhum fogo porei debaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 24, 'Invocai logo vós no nome de vossos deuses, e eu invocarei no nome do SENHOR: e o Deus que responder por fogo, esse seja Deus. E todo o povo respondeu, dizendo: Bem dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 25, 'Então Elias disse aos profetas de Baal: Escolhei-vos o um boi, e fazei primeiro, pois que vós sois os mais: e invocai no nome de vossos deuses, mas não ponhais fogo debaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 26, 'E eles tomaram o boi que lhes foi dado, e prepararam-no, e invocaram no nome de Baal desde a manhã até o meio dia, dizendo: Baal, responde-nos! Mas não havia voz, nem quem respondesse; entretanto, eles andavam saltando próximo do altar que haviam feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 27, 'E aconteceu ao meio dia, que Elias se ridicularizava deles, dizendo: Gritai em alta voz, que deus é: talvez esteja conversando, ou tem alguma ocupação, ou está caminhando; acaso dorme, e despertará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 28, 'E eles clamavam a grandes vozes, e cortavam-se com espadas e com lancetas conforme a seu costume, até jorrar o sangue sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 29, 'E quando passou o meio dia, e eles profetizaram até o tempo do sacrifício da oferta, e não havia voz, nem quem respondesse nem escutasse;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 30, 'Elias disse então a todo o povo: Aproximai-vos a mim. E todo o povo se chegou a ele: e ele reparou o altar do SENHOR que estava arruinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 31, 'E tomando Elias doze pedras, conforme ao número das tribos dos filhos de Jacó, ao qual havia sido palavra do SENHOR, dizendo: Israel será teu nome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 32, 'Edificou com as pedras um altar no nome do SENHOR: depois fez uma sulco ao redor do altar, quanto cabiam duas medidas de semente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 33, 'Pôs logo a lenha, e cortou o boi em pedaços, e o pôs sobre a lenha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 34, 'E disse: Enchei quatro cântaros de água, e derramai-a sobre o holocausto e sobre a lenha. E disse: Fazei-o outra vez; e outra vez o fizeram. Disse ainda: Fazei-o a terceira vez; e fizeram-no a terceira vez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 35, 'De maneira que as águas corriam ao redor do altar; e havia também enchido de água o sulco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 36, 'E quando chegou a hora de oferecer-se o holocausto, chegou-se o profeta Elias, e disse: SENHOR Deus de Abraão, de Isaque, e de Israel, seja hoje manifesto que tu és Deus em Israel, e que eu sou teu servo, e que por mandado teu fiz todas estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 37, 'Responde-me, SENHOR, responde-me; para que conheça este povo que tu, ó SENHOR, és o Deus, e que tu voltaste atrás o coração deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 38, 'Então caiu fogo do SENHOR, o qual consumiu o holocausto, e a lenha, e as pedras, e o pó, e ainda sugou as águas que estavam no sulco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 39, 'E vendo-o todo o povo, caíram sobre seus rostos, e disseram: o SENHOR é o Deus! o SENHOR é o Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 40, 'E disse-lhes Elias: Prendei aos profetas de Baal, que não escape ninguém. E eles os prenderam; e levou-os Elias ao ribeiro de Quisom, e ali os degolou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 41, 'E então Elias disse a Acabe: Sobe, come e bebe; porque uma grande chuva faz ruído.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 42, 'E Acabe subiu a comer e a beber. E Elias subiu ao cume do Carmelo; e prostrando-se em terra, pôs seu rosto entre os joelhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 43, 'E disse a seu criado: Sobe agora, e olha até o mar. E ele subiu, e olhou, e disse: Não há nada. E ele lhe voltou a dizer: Volta sete vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 44, 'E à sétima vez disse: Eu vejo uma pequena nuvem como a palma da mão de um homem, que sobe do mar. E ele disse: Vai, e dize a Acabe: Unge e desce, porque a chuva não te interrompa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 45, 'E aconteceu, estando em isto, que os céus se escureceram com nuvens e vento; e houve uma grande chuva. E subindo Acabe, veio a Jezreel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 18, 46, 'E a mão do SENHOR foi sobre Elias, o qual cingiu seus lombos, e veio correndo diante de Acabe até chegar a Jezreel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 1, 'E Acabe deu a notícia a Jezabel de tudo o que Elias havia feito, de como havia matado à espada a todos os profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 2, 'Então enviou Jezabel a Elias um mensageiro, dizendo: Assim me façam os deuses, e assim me acrescentem, se amanhã a estas horas eu não haja posto tua pessoa como a de um deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 3, 'Vendo, pois, o perigo, levantou-se e foi-se por salvar sua vida, e veio a Berseba, que é em Judá, e deixou ali seu criado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 4, 'E ele se foi pelo deserto um dia de caminho, e veio e sentou-se debaixo de um junípero; e desejando morrer, disse: Basta já, ó SENHOR, tira minha alma; que não sou eu melhor que meus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 5, 'E lançando-se debaixo do junípero, ficou dormido: e eis que logo um anjo que lhe tocou, e lhe disse: Levanta-te, come.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 6, 'Então ele olhou, e eis que a sua cabeceira uma torta cozida sobre as ascuas, e um vaso de água: e comeu e bebeu e voltou-se a dormir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 7, 'E voltando o anjo do SENHOR a segunda vez, tocou-lhe, dizendo: Levanta-te, come: porque grande caminho te resta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 8, 'Levantou-se, pois, e comeu e bebeu; e caminhou com a força daquela comida quarenta dias e quarenta noites, até o monte de Deus, Horebe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 9, 'E ali se meteu em uma cova, de onde teve a noite. E foi a ele palavra do SENHOR, o qual lhe disse: Que fazes aqui, Elias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 10, 'E ele respondeu: Tenho sentido um zelo intenso pelo SENHOR Deus dos exércitos; porque os filhos de Israel deixaram tua aliança, derrubaram teus altares, e mataram à espada teus profetas: e eu só restei, e me buscam para tirar-me a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 11, 'E ele lhe disse: Sai fora, e põe-te no monte diante do SENHOR. E eis que o SENHOR que passava, e um grande e poderoso vento que rompia os montes, e quebrava as penhas diante do SENHOR: mas o SENHOR não estava no vento. E depois do vento um terremoto: mas o SENHOR não estava no terremoto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 12, 'E depois do terremoto um fogo: mas o SENHOR não estava no fogo. E depois do fogo uma voz agradável e suave.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 13, 'E quando o ouviu Elias, cobriu seu rosto com seu manto, e saiu, e parou-se à porta da cova. E eis que chegou uma voz a ele, dizendo: Que fazes aqui, Elias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 14, 'E ele respondeu: Tenho sentido um zelo intenso pelo SENHOR Deus dos exércitos; porque os filhos de Israel deixaram tua aliança, derrubaram teus altares, e mataram à espada teus profetas: e eu só restei, e me buscam para tirar-me a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 15, 'E disse-lhe o SENHOR: Vai, volta-te por teu caminho, pelo deserto de Damasco: e chegarás, e ungirás a Hazael por rei da Síria;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 16, 'E a Jeú, filho de Ninsi, ungirás por rei sobre Israel; e a Eliseu filho de Safate, de Abel-Meolá, ungirás para que seja profeta em lugar de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 17, 'E será, que o que escapar da espada, de Hazael, Jeú o matará; e o que escapar da espada de Jeú, Eliseu o matará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 18, 'E eu farei que restem em Israel sete mil; todos os joelhos que não se encurvaram a Baal, e bocas todas que não o beijaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 19, 'E partindo-se ele dali, achou a Eliseu filho de Safate, que arava com doze juntas diante de si; e ele era um dos doze trabalhadores. E passando Elias por diante dele, lançou sobre ele seu manto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 20, 'Então deixando ele os bois, veio correndo após Elias, e disse: Rogo-te que me deixes beijar meu pai e minha mãe, e logo te seguirei. E ele lhe disse: Vai, volta: que te fiz eu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 19, 21, 'E interrompeu de segui-lo, tomou um par de bois, e os matou, e com o arado dos bois cozeu a carne deles, e deu-a ao povo que comessem. Depois se levantou, e foi atrás de Elias, e o servia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 1, 'Então Ben-Hadade, rei da Síria, juntou a todo seu exército, e com ele trinta e dois reis, com cavalos e carros: e subiu, e pôs cerco a Samaria, e combateu-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 2, 'E enviou mensageiros à cidade a Acabe rei de Israel, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 3, 'Assim disse Ben-Hadade: Tua prata e teu ouro são meus, e tuas mulheres e teus filhos belos são meus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 4, 'E o rei de Israel respondeu, e disse: Como tu dizes, rei senhor meu, eu sou teu, e tudo o que tenho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 5, 'E voltando os mensageiros outra vez, disseram: Assim disse Ben-Hadade: Eu te enviei a dizer: Tua prata e teu ouro, e tuas mulheres e teus filhos me darás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 6, 'Além disso, amanhã a estas horas enviarei eu a ti meus servos, os quais vasculharão a tua casa, e as casas de teus servos; e tomarão com suas mãos, e levarão tudo o que for precioso que tiveres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 7, 'Então o rei de Israel chamou a todos os anciãos da terra, e disse-lhes: Entendei, e vede agora como este não busca a não ser mal: pois que enviou a mim por minhas mulheres e meus filhos, e por minha prata e por meu ouro; e eu não se o neguei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 8, 'E todos os anciãos e todo o povo lhe responderam: Não lhe obedeças, nem faças o que te pede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 9, 'Então ele respondeu aos embaixadores de Ben-Hadade: Dizei ao rei meu senhor: Farei tudo o que mandaste a teu servo ao princípio; mas isto não posso fazer. E os embaixadores foram, e deram-lhe a resposta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 10, 'E Ben-Hadade converteu a enviar-lhe a dizer: Assim me façam os deuses, e assim me acrescentem, que o pó de Samaria não bastará aos punhos de todo o povo que me segue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 11, 'E o rei de Israel respondeu, e disse: Dizei-lhe, que não se glorie o que se cinge, como o que já se descinge.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 12, 'E quando ele ouviu esta palavra, estando bebendo com os reis nas tendas, disse a seus servos: Ponde. E eles puseram contra a cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 13, 'E eis que um profeta se chegou a Acabe rei de Israel; e lhe disse: Assim disse o SENHOR: Viste esta grande multidão? Eis que eu a entregarei hoje em tua mão, para que conheças que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 14, 'E respondeu Acabe: Por meio de quem? E ele disse: Assim disse o SENHOR: Por meio dos criados dos príncipes das províncias. E disse Acabe: Quem começará a batalha? E ele respondeu: Tu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 15, 'Então ele revistou os criados dos príncipes das províncias, os quais foram duzentos trinta e dois. Em seguida revistou todo o povo, todos os filhos de Israel, que foram sete mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 16, 'E saíram a meio dia. E estava Ben-Hadade bebendo, embriagado nas tendas, ele e os reis, os trinta e dois reis que haviam vindo em sua ajuda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 17, 'E os criados dos príncipes das províncias saíram os primeiros. E havia Ben-Hadade enviado quem lhe deu aviso, dizendo: Saíram homens de Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 18, 'Ele então disse: Se saíram por paz, tomai-os vivos; e se saíram para lutar, tomai-os vivos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 19, 'Saíram, pois da cidade os criados dos príncipes das províncias, e após eles o exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 20, 'E feriu cada um ao que vinha contra si: e fugiram os sírios, seguindo-os os de Israel. E o rei da Síria, Ben-Hadade, se escapou em um cavalo com alguma gente de cavalaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 21, 'E saiu o rei de Israel, e feriu a cavaleiros, e os carros; e derrotou os sírios com grande estrago.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 22, 'Chegando-se logo o profeta ao rei de Israel, lhe disse: Vai, fortalece-te, e considera e olha o que hás de fazer; porque passado o ano, o rei da Síria há de vir contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 23, 'E os servos do rei da Síria lhe disseram: seus deuses são deuses dos montes, por isso nos venceram; mas se lutássemos com eles na planície, se verá se não os vencemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 24, 'Faze, pois assim: Tira aos reis cada um de seu posto, e põe capitães em lugar deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 25, 'E tu, forma-te outro exército como o exército que perdeste, cavalos por cavalos, e carros por carros; logo lutaremos com eles em campo raso, e veremos se não os vencemos. E ele lhes deu ouvido, e o fez assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 26, 'Passado o ano, Ben-Hadade revistou os sírios, e veio a Afeque a lutar contra Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 27, 'E os filhos de Israel foram também inspecionados, e tomando provisões foram-lhes ao encontro; e assentaram acampamento os filhos de Israel diante deles, como dois pequenos rebanhos de cabras; e os sírios enchiam a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 28, 'Chegando-se então o homem de Deus ao rei de Israel, falou-lhe dizendo: Assim disse o SENHOR: Porquanto os sírios disseram, o SENHOR é Deus dos montes, não Deus dos vales, eu entregarei toda esta grande multidão em tua mão, para que conheçais que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 29, 'Sete dias tiveram assentado o acampamento uns diante dos outros, e ao sétimo dia começou a batalha: e mataram os filhos de Israel dos sírios em um dia cem mil homens a pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 30, 'Os demais fugiram a Afeque, à cidade: e o muro caiu sobre vinte e sete mil homens que haviam restado. Também Ben-Hadade veio fugindo à cidade, e escondia-se de câmara em câmara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 31, 'Então seus servos lhe disseram: Eis que, ouvimos dos reis da casa de Israel que são reis clementes: ponhamos, pois, agora sacos em nossos lombos, e cordas em nossas cabeças, e saiamos ao rei de Israel: porventura te salvará a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 32, 'Cingiram, pois seus lombos de sacos, e cordas a suas cabeças, e vieram ao rei de Israel, e disseram-lhe: Teu servo Ben-Hadade disse: Rogo-te que viva minha alma. E ele respondeu: Se ele vive ainda, meu irmão é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 33, 'Isto tomaram aqueles homens por bom presságio, e logo tomaram esta palavra de sua boca, e disseram: Teu irmão Ben-Hadade! E ele disse: Ide, e trazei-lhe. Ben-Hadade então se apresentou a Acabe, e ele lhe fez subir em um carro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 34, 'E disse-lhe Ben-Hadade: As cidades que meu pai tomou ao teu, eu as restituirei; e faze praças em Damasco para ti, como meu pai as fez em Samaria. E eu, disse Acabe, te deixarei partir com esta aliança. Fez, pois com ele aliança, e deixou-lhe ir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 35, 'Então um homem dos filhos dos profetas disse a seu companheiro por palavra de Deus: Fere-me agora. Mas o outro homem não quis ferir-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 36, 'E ele lhe disse: Porquanto não obedeceste à palavra do SENHOR, eis que em apartando-te de mim, te ferirá um leão. E quando se separou dele, encontrou-lhe um leão, e feriu-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 37, 'Encontrou-se logo com outro homem, e disse-lhe: Fere-me agora. E o homem lhe deu um golpe, e fez-lhe uma ferida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 38, 'E o profeta se foi, e pôs-se diante do rei no caminho, e disfarçou-se com um véu sobre os olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 39, 'E quando o rei passava, ele deu vozes ao rei, e disse: Teu servo saiu entre a tropa: e eis que um, que estava a sair, trouxe-me um homem, dizendo: Guarda a este homem, e se ele vier a faltar, tua vida será pela dele, ou pagarás um talento de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 40, 'E quando o teu servo estava ocupado à uma parte e à outra, ele desapareceu. Então o rei de Israel lhe disse: Essa será tua sentença: tu a pronunciaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 41, 'Porém ele se tirou logo o véu de sobre seus olhos, e o rei de Israel conheceu que era dos profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 42, 'E ele lhe disse: Assim disse o SENHOR: Porquanto soltaste da mão o homem de meu anátema, tua vida será pela sua, e teu povo pelo seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 20, 43, 'E o rei de Israel se foi a sua casa triste e irritado, e chegou a Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 1, 'Passados estes negócios, aconteceu que Nabote de Jezreel tinha em Jezreel uma vinha junto ao palácio de Acabe rei de Samaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 2, 'E Acabe falou a Nabote, dizendo: Dá-me tua vinha para uma horta de legumes, porque está próxima, junto a minha casa, e eu te darei por ela outra vinha melhor que esta; ou se melhor te parecer, te pagarei seu valor em dinheiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 3, 'E Nabote respondeu a Acabe: Guarde-me o SENHOR de que eu te dê a ti a propriedade de meus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 4, 'E veio Acabe à sua casa triste e irritado, pela palavra que Nabote de Jezreel havia lhe respondido, dizendo: Não te darei a propriedade de meus pais. E deitou-se em sua cama, e virou seu rosto, e não comeu pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 5, 'E veio a ele sua mulher Jezabel, e disse-lhe: Por que está tão triste teu espírito, e não comes pão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 6, 'E ele respondeu: Porque falei com Nabote de Jezreel, e disse-lhe que me desse sua vinha por dinheiro, ou que, se mais quisesse, eu lhe daria outra vinha por ela; e ele respondeu: Eu não te darei minha vinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 7, 'E sua mulher Jezabel lhe disse: És tu agora rei sobre Israel? Levanta-te, e come pão, e alegra-te: eu te darei a vinha de Nabote de Jezreel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 8, 'Então ela escreveu cartas em nome de Acabe, e selou-as com seu anel e enviou-as aos anciãos e aos principais que moravam em sua cidade com Nabote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 9, 'E as cartas que escreveu diziam assim: Proclamai jejum, e ponde a Nabote em posição de destaque do povo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 10, 'E ponde dois homens perversos diante dele, que testemunhem contra ele, e digam: Tu blasfemaste a Deus e ao rei. E então o tirai, e apedrejai-o, e morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 11, 'E os de sua cidade, os anciãos e os principais que moravam em sua cidade, o fizeram como Jezabel lhes mandou, conforme o escrito nas cartas que ela lhes havia enviado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 12, 'E promulgaram jejum, e assentaram a Nabote em posição de destaque do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 13, 'Vieram então dois homens perversos, e sentaram-se diante dele: e aqueles homens de Belial testemunharam contra Nabote diante do povo, dizendo: Nabote blasfemou a Deus e ao rei. E tiraram-no fora da cidade, e apedrejaram-no com pedras, e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 14, 'Depois enviaram a dizer a Jezabel: Nabote foi apedrejado e morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 15, 'E quando Jezabel ouviu que Nabote havia sido apedrejado e morto, disse a Acabe: Levanta-te e possui a vinha de Nabote de Jezreel, que não te a quis dar por dinheiro; porque Nabote não vive, mas sim que está morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 16, 'E ouvindo Acabe que Nabote era morto, levantou-se para descer à vinha de Nabote de Jezreel, para tomar possessão dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 17, 'Então veio a palavra do SENHOR a Elias Tisbita, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 18, 'Levanta-te, desce a encontrar-te com Acabe rei de Israel, que está em Samaria: eis que ele está na vinha de Nabote, à qual desceu para tomar possessão dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 19, 'E falar-lhe hás, dizendo: Assim disse o SENHOR: Não mataste e também possuíste? E voltarás a falar-lhe, dizendo: Assim disse o SENHOR: No mesmo lugar de onde lamberam os cães o sangue de Nabote, os cães lamberão também teu sangue, o teu mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 20, 'E Acabe disse a Elias: Achaste-me, inimigo meu? E ele respondeu: Eu te encontrei, porque te vendeste a fazer o mal diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 21, 'Eis que eu trago mal sobre ti, e varrerei tua posteridade, e exterminarei de Acabe todo macho, ao escravo e ao livre em Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 22, 'E eu porei tua casa como a casa de Jeroboão filho de Nebate, e como a casa de Baasa filho de Aías; pela provocação com que me provocaste à ira, e com que fizeste pecar a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 23, 'De Jezabel também falou o SENHOR, dizendo: Os cães comerão a Jezabel no muro de Jezreel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 24, 'O que de Acabe for morto na cidade, cães lhe comerão: e o que for morto no campo, comê-lo-ão as aves do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 25, '(À verdade ninguém foi como Acabe, que se vendeu a fazer o mal aos olhos do SENHOR; porque Jezabel sua mulher o incitava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 26, 'Ele foi em grande maneira abominável, caminhando após o os ídolos, conforme a tudo o que fizeram os amorreus, aos quais lançou o SENHOR diante dos filhos de Israel.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 27, 'E aconteceu quando Acabe ouviu estas palavras, que rasgou suas roupas, e pôs saco sobre sua carne, e jejuou, e dormiu em saco, e andou humilhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 28, 'Então veio a palavra do SENHOR a Elias Tisbita, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 21, 29, 'Não viste como Acabe se humilhou diante de mim? Pois porquanto se humilhou diante de mim, não trarei o mal em seus dias: nos dias de seu filho trarei o mal sobre sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 1, 'Três anos passaram sem guerra entre os sírios e Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 2, 'E aconteceu ao terceiro ano, que Josafá rei de Judá desceu ao rei de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 3, 'E o rei de Israel disse a seus servos: Não sabeis que Ramote de Gileade e nossa? Porém ficamos quietos, sem a tomar da mão do rei da Síria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 4, 'E disse a Josafá: Queres vir comigo a lutar contra Ramote de Gileade? E Josafá respondeu ao rei de Israel: Como eu, assim tu; e como meu povo, assim teu povo; e como meus cavalos, teus cavalos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 5, 'E disse logo Josafá ao rei de Israel: Eu te rogo que consultes hoje a palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 6, 'Então o rei de Israel juntou os profetas, como quatrocentos homens, aos quais disse: Irei à guerra contra Ramote de Gileade, ou a deixarei? E eles disseram: Sobe; porque o Senhor a entregará em mão do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 7, 'E disse Josafá: Há ainda aqui algum profeta do SENHOR, pelo qual consultemos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 8, 'E o rei de Israel respondeu a Josafá: Ainda há um homem pelo qual poderíamos consultar ao SENHOR, Micaías, filho de Inlá: mas eu lhe aborreço porque nunca me profetiza bem, a não ser somente mal. E Josafá disse: Não fale o rei assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 9, 'Então o rei de Israel chamou a um eunuco, e disse-lhe: traze logo a Micaías filho de Inlá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 10, 'E o rei de Israel e Josafá rei de Judá estavam sentados cada um em sua cadeira, vestidos de suas roupas reais, na praça junto à entrada da porta de Samaria; e todos os profetas profetizavam diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 11, 'E Zedequias filho de Quenaaná se havia feito uns chifres de ferro, e disse: Assim disse o SENHOR: Com estes chifrarás aos siros até acabá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 12, 'E todos os profetas profetizavam da mesma maneira, dizendo: Sobe a Ramote de Gileade, e serás próspero; que o SENHOR a dará em mão do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 13, 'E o mensageiro que havia ido a chamar a Micaías, falou-lhe, dizendo: Eis que as palavras dos profetas unanimemente anunciam o bem ao rei; seja agora a tua palavra conforme à palavra de algum deles, e anuncia o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 14, 'E Micaías respondeu: Vive o SENHOR, que o que o SENHOR me falar, isso direi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 15, 'Veio, pois, ao rei, e o rei lhe disse: Micaías, devemos ir lutar por Ramote de Gileade, ou a deixaremos? E ele respondeu: Sobe, que serás próspero, e o SENHOR a entregará na mão do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 16, 'E o rei lhe disse: Até quantas vezes te farei jurar que não me digas a não ser a verdade no nome do SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 17, 'Então ele disse: Eu vi a todo Israel disperso pelos montes, como ovelhas que não têm pastor: e o SENHOR disse: Estes não têm senhor: volte-se cada um a sua casa em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 18, 'E o rei de Israel disse a Josafá: Não te o havia eu dito? Nenhuma coisa boa profetizará ele acerca de mim, a não ser somente mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 11, '1 Reis', '1Rs', 22, 19, 'Então ele disse: Ouve, pois, a palavra do SENHOR: Eu vi o SENHOR sentado em seu trono, e todo o exército dos céus estava junto a ele, à sua direita e à sua esquerda.')
